Illustrative example showcasing the compiler's optimization:

```c++
class MyClass {
public:
    MyClass() { std::cout << "Constructor called\n"; }
    MyClass(const MyClass& other) { std::cout << "Copy Constructor called\n"; }
    MyClass(MyClass&& other) noexcept { std::cout << "Move Constructor called\n"; }
    ~MyClass() { std::cout << "Destructor called\n"; }
};

MyClass createMyClass() {
    MyClass obj;
    return obj; // RVO candidate
}

MyClass createMyClass2() {
    MyClass obj;
    return std::move(obj); // still RVO possible, but move is expressed
}

int main() {
    MyClass myObj1 = createMyClass();
    MyClass myObj2 = createMyClass2();
    return 0;
}
```

